<script lang="ts">import DashboardContent from '$lib/components/DashboardContent.svelte';import{Button}from'$lib/components/ui/button/index.js';import{Plus}from'lucide-svelte';import{enhance}from'$app/forms';import{dispatchToast}from'$lib/notifications';const{data}= $props();let open=$state(false);const rows=$derived(data.graduations);function submit(){return async({result,update}:any)=>{if(result.type==='success'){open=false;dispatchToast('Saved',result.data?.message??'Saved')}else if(result.type==='failure')dispatchToast('Error',result.data?.message??'Could not save');await update();}}</script>
<DashboardContent title="Graduation & Exit" subtitle="Clearance, graduation records and long-term student retention">{#snippet headerActions()}<Button size="sm" onclick={()=>open=true}><Plus class="h-3.5 w-3.5"/> Record Graduation</Button>{/snippet}<div class="mb-5 rounded-xl border border-primary/20 bg-primary/5 p-4 text-sm text-primary">Graduation archives the active student record but does not delete it. Student 360 history remains available for reporting.</div><div class="overflow-hidden rounded-xl border border-border bg-white"><div class="grid grid-cols-[1.5fr_1fr_1fr_1fr_1fr] gap-3 border-b bg-muted/40 px-4 py-3 text-xs font-semibold text-muted-foreground"><span>Student</span><span>Year</span><span>Graduation</span><span>Clearance</span><span>Completion</span></div>{#each rows as g}<div class="grid grid-cols-[1.5fr_1fr_1fr_1fr_1fr] gap-3 border-b px-4 py-3 last:border-0"><div><p class="text-sm font-medium">{g.students?.first_name} {g.students?.last_name}</p><p class="text-[11px] text-muted-foreground">{g.students?.admission_no}</p></div><span class="text-sm">{g.academic_years?.name??'—'}</span><span class="text-sm">{g.graduation_date}</span><span class="text-sm capitalize">{g.clearance_status}</span><span class="text-sm capitalize">{g.completion_status}</span></div>{:else}<div class="p-12 text-center text-sm text-muted-foreground">No graduation records.</div>{/each}</div></DashboardContent>
{#if open}<div class="fixed inset-0 z-50 flex items-center justify-center bg-black/30 p-4"><div class="w-full max-w-lg rounded-2xl bg-white shadow-xl"><div class="border-b px-6 py-4"><h2 class="font-semibold">Record Graduation</h2></div><form method="POST" action="?/graduate" use:enhance={submit} class="grid gap-4 px-6 py-5"><label class="text-xs font-medium">Student<select name="student_id" required class="field"><option value="">Select student</option>{#each data.students as s}<option value={s.id}>{s.admission_no} — {s.first_name} {s.last_name}</option>{/each}</select></label><label class="text-xs font-medium">Academic Year<select name="academic_year_id" required class="field"><option value="">Select year</option>{#each data.years as y}<option value={y.id}>{y.name}</option>{/each}</select></label><label class="text-xs font-medium">Graduation Date<input name="graduation_date" type="date" required class="field"/></label><label class="text-xs font-medium">Cohort<input name="cohort" class="field" placeholder="Class of 2026"/></label><div class="grid grid-cols-2 gap-3"><label class="text-xs font-medium">Clearance<select name="clearance_status" class="field"><option value="pending">Pending</option><option value="cleared">Cleared</option><option value="blocked">Blocked</option></select></label><label class="text-xs font-medium">Completion<select name="completion_status" class="field"><option value="completed">Completed</option><option value="deferred">Deferred</option><option value="not_completed">Not Completed</option></select></label></div><label class="text-xs font-medium">Certificate Reference<input name="certificate_reference" class="field"/></label><label class="text-xs font-medium">Notes<textarea name="notes" class="field" rows="2"></textarea></label><div class="flex justify-end gap-2"><Button type="button" variant="outline" onclick={()=>open=false}>Cancel</Button><Button type="submit">Record Graduation</Button></div></form></div></div>{/if}<style>:global(.field){width:100%;margin-top:.3rem;border:1px solid hsl(var(--border));border-radius:.5rem;padding:.55rem .7rem;font-size:.875rem;outline:none}</style>
